MERGE [purchase].[PurchaseSeries] t USING(VALUES('PUR','PUR',1,6,1))s([Code],[Prefix],[NextNo],[Length],[Default]) ON t.[SeriesCode]=s.[Code] WHEN MATCHED THEN UPDATE SET [Prefix]=s.[Prefix],[NumberLength]=s.[Length],[IsDefault]=s.[Default],[IsActive]=1 WHEN NOT MATCHED THEN INSERT([SeriesCode],[Prefix],[NextNumber],[NumberLength],[IsDefault])VALUES(s.[Code],s.[Prefix],s.[NextNo],s.[Length],s.[Default]);
